def el(cls,k,body,style=''):
 return f'<div class="{cls}" data-el="inflexion-{k}"'+(f' style="{style}"' if style else '')+'>'+body+'</div>'
def place(s,c,r,w,h):
 return s.replace('>',' style="'+f'grid-column:{c} / span {w}; grid-row:{r} / span {h}'+'">',1) if ' style=' not in s.split('>')[0] else s.replace('style="',f'style="grid-column:{c} / span {w}; grid-row:{r} / span {h}; ',1)
def head(s,note='',big=False,center=False):
 return el('headline'+(' big' if big else '')+(' center' if center else ''),'headline',f'<h2>{s}</h2>'+ (f'<p class="note">{note}</p>' if note else ''))
def prose(s):return el('prose','prose',''.join(f'<p>{p}</p>' for p in s.split('\n')))
def card(name,note='',fig='',kick='',variant='',mark=''):
 if 'class="seat" data-ph=' in mark:
  import re
  n=re.search(r'data-ph="(\d+)"',mark).group(1);mark=f'<div class="mark seat" data-ph="{n}"></div>'
 else:mark=f'<div class="mark">{mark}</div>' if mark else ''
 return el('card '+variant,'card','<div class="parts">'+mark+(f'<p class="kick">{kick}</p>' if kick else '')+(f'<p class="fig">{fig}</p>' if fig else '')+f'<p class="name">{name}</p>'+(f'<p class="note">{note}</p>' if note else '')+'</div>')
def lists(items,cls=''):
 return el('list '+cls,'list',''.join('<div class="item"><p class="name">'+a+'</p><p class="note">'+b+'</p></div>' for a,b in items))
def callout(s):return el('callout','callout','<p>'+s+'</p>')
def frame(n):return el('frame','image-frame',f'<div class="seat" data-ph="{n}"></div>')
def stat(fig,name,note=''):
 return el('stat','metric',f'<div class="parts"><p class="fig">{fig}</p><p class="name">{name}</p><p class="note">{note}</p></div>')
def bars(vals,labs,maxv=100,h=False):return el('bars'+(' h' if h else ''),'chart-bar',''.join(f'<div class="bar'+(' on' if i==len(vals)-1 else '')+f'" style="--v:{v}"><b>{v}</b><span>{l}</span></div>' for i,(v,l) in enumerate(zip(vals,labs))),f'--max:{maxv}')
def areas(vals,labs,maxv=100,second=None):
 sr=''
 for k,vs in enumerate([vals,second] if second else [vals]):sr+=f'<div class="series tone-{k+1}"><b class="name">'+(['주요 지표','비교 지표'][k])+'</b>'+''.join(f'<div class="pt" style="--v:{v}"><b>{v}</b></div>' for v in vs)+'</div>'
 return el('areas','chart-area',sr+'<div class="axis">'+''.join(f'<span>{l}</span>' for l in labs)+'</div>',f'--max:{maxv}')
def donut(v,name):return el('donut','chart-donut',f'<b class="fig">{v}<small>%</small></b><p class="name">{name}</p>',f'--v:{v}')
def group(items):return '<div class="group">'+''.join(items)+'</div>'
def stack(items):return '<div class="stack">'+''.join(items)+'</div>'
def agenda(items,start=1):return el('agenda','agenda',''.join(f'<div class="entry"><b class="mark">{i+start:02}</b><p class="name">{a}</p><p class="note">{b}</p></div>' for i,(a,b) in enumerate(items)))
def timeline(items):return el('track col','timeline',''.join(f'<div class="stop"><p class="kick">{a}</p><p class="name">{b}</p><p class="note">{c}</p></div>' for a,b,c in items))
